package com.backend.gapfinder.view.dto;

import java.time.LocalDateTime;

import com.backend.gapfinder.model.models.StudyPeriodModel;

import lombok.Data;

@Data
public class StudyPeriodDTO {

    // Id given by the server (the app uses it to remove the period)
    private Long id;

    // Id of the student who is studying
    private Long userId;

    // Start of the study period
    private LocalDateTime startTime;

    // End of the study period
    private LocalDateTime endTime;

    // Gap the student chose to hide (null if none)
    private Long gapId;

    // Id generated by the app (UUID)
    private String clientId;

    // Date and time when the server stored the period
    private LocalDateTime createdAt;

    public static StudyPeriodDTO from(StudyPeriodModel period) {
        StudyPeriodDTO dto = new StudyPeriodDTO();
        dto.setId(period.getId());
        dto.setUserId(period.getUser().getId());
        dto.setStartTime(period.getStartTime());
        dto.setEndTime(period.getEndTime());
        dto.setGapId(period.getGapId());
        dto.setClientId(period.getClientId());
        dto.setCreatedAt(period.getCreatedAt());
        return dto;
    }
}
